const url = new URL(props.bookingUrl);
const pathParts = url.pathname.split("/").filter(Boolean);
pathParts.pop(); // Remove slug
let prefix = "/";
if (pathParts.length > 0) {
  prefix = `/${pathParts.join("/")}/`;
}
return `${url.protocol}//${url.hostname}${prefix}`;

